package io.github.markpollack.journal.ocsf.writer;

import java.io.IOException;
import java.io.InputStream;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;

/**
 * The writer side of Journal's MCP protocol binding ({@code ocsf/mcp/binding.json}, generated by
 * {@link McpBindingGenerator} from the pinned official JSON Schemas): builds the typed {@code mcp_protocol_object} for a
 * protocol object, or for the members a CLI projected of one ({@link McpEmbedder} does the embedding), and names the
 * official definitions and binding shapes a file must declare for a reader to extract and validate it offline.
 */
public final class McpBinding {

    public static final String RESOURCE = "/ocsf/mcp/binding.json";

    /** projection_id values of {@code mcp_protocol_object}. */
    public static final int COMPLETE = 1;
    public static final int PARTIAL = 2;
    public static final int SCHEMA_EXAMPLE = 3;
    static final Map<Integer, String> PROJECTION = Map.of(0, "Unknown", 1, "Complete protocol object", 2, "Partial projection", 3, "Schema example", 99, "Other");

    private final Jv document;
    private final Jv.Obj objects;
    private final Map<String, Jv> schemas = new java.util.concurrent.ConcurrentHashMap<>();

    /** Lazily loaded once (initialization-on-demand holder). */
    private static final class Bundled {
        static final McpBinding INSTANCE = new McpBinding(Jv.parse(resource(RESOURCE)));
    }

    McpBinding(Jv document) {
        this.document = document;
        this.objects = (Jv.Obj) document.member("objects");
    }

    public static McpBinding bundled() {
        return Bundled.INSTANCE;
    }

    private static String resource(String name) {
        try (InputStream in = McpBinding.class.getResourceAsStream(name)) {
            if (in == null) {
                throw new IllegalStateException("missing resource " + name);
            }
            return new String(in.readAllBytes(), StandardCharsets.UTF_8);
        }
        catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    public Jv document() {
        return document;
    }

    /** The binding node of a definition in a revision, or {@code null} when the revision does not define it. */
    public Jv definition(String revision, String definition) {
        return document.path("revisions", revision, "definitions", definition);
    }

    /** The {@code mcp_protocol_object} slot attribute a definition's object is held in. */
    public String slot(String revision, String definition) {
        Jv node = require(revision, definition);
        String kind = node.member("kind").text();
        return switch (kind) {
            case "object", "variant" -> node.member("object").text();
            case "map" -> node.member("object").text() + "_list";
            default -> throw new IllegalArgumentException(definition + " of " + revision + " is " + kind + ", not an object; it has no protocol-object slot");
        };
    }

    /**
     * One element of {@code mcp_observation.protocol_objects}: the value embedded as {@code definition} of
     * {@code revision}, labelled with its projection and, for a partial projection, the protocol-required members of
     * the definition that the projected value lacks.
     */
    public Jv.Obj protocolObject(String revision, String definition, Jv value, int projection, String projectionBasis) {
        Jv node = require(revision, definition);
        McpEmbedder embedder = new McpEmbedder(objects, revision);
        Jv embedded = embedder.embed(node, value);
        if (embedded == null) {
            throw new IllegalArgumentException("a " + definition + " must be a JSON object; got " + Jv.write(value));
        }
        Jv.Obj o = new Jv.Obj().put("protocol_definition", definition).put("binding_revision", revision)
                .put("projection_id", projection).put("projection", PROJECTION.get(projection)).put("projection_basis", projectionBasis);
        Jv.Arr missing = projection == PARTIAL ? missingRequired(embedder, node, value) : new Jv.Arr();
        if (!missing.elements().isEmpty()) {
            o.put("missing_required", missing);
        }
        return o.put(slot(revision, definition), embedded);
    }

    private static Jv.Arr missingRequired(McpEmbedder embedder, Jv node, Jv value) {
        Jv.Arr missing = new Jv.Arr();
        if ("object".equals(node.member("kind").text())) {
            for (Jv r : embedder.shape(node.member("object").text()).member("required").elements()) {
                if (value.member(r.text()) == null) {
                    missing.add(r);
                }
            }
        }
        return missing;
    }

    private Jv require(String revision, String definition) {
        Jv node = definition(revision, definition);
        if (node == null) {
            throw new IllegalArgumentException("MCP " + revision + " defines no " + definition);
        }
        return node;
    }

    /** The pinned official schema.json of a revision, bundled from {@code schema/protocol/mcp}. */
    public Jv officialSchema(String revision) {
        return schemas.computeIfAbsent(revision, r -> Jv.parse(resource("/ocsf/mcp/schema/" + r + "/schema.json")));
    }

    /** The pin record of a revision ({@code PINS.json}). */
    public Jv pin(String revision) {
        for (Jv r : document.path("pins", "revisions").elements()) {
            if (revision.equals(r.member("revision").text())) {
                return r;
            }
        }
        throw new IllegalArgumentException("no pinned MCP revision " + revision);
    }

    // ------------------------------------------------------------------------------------------ declaration closure

    /** Official definition names and binding object names a reader needs. */
    public record Closure(Set<String> definitions, Set<String> objects) {
    }

    /**
     * The official definitions and binding shapes needed to read and validate objects of {@code definitions} in
     * {@code revision}: the pinned JSON Schema definitions reachable through {@code $ref} from them, and the binding
     * objects reachable from those definitions' nodes.
     */
    public Closure closure(String revision, Set<String> definitions) {
        Set<String> official = officialClosure((Jv.Obj) officialSchema(revision).member("$defs"), revision, definitions);
        Set<String> shapes = new TreeSet<>();
        Deque<Jv> nodes = new ArrayDeque<>();
        for (String d : official) {
            Jv n = definition(revision, d);
            if (n != null) {
                nodes.push(n);
            }
        }
        McpEmbedder shapesOf = new McpEmbedder(objects, revision);
        while (!nodes.isEmpty()) {
            Jv n = nodes.pop();
            if (n.member("items") != null) {
                nodes.push(n.member("items"));
            }
            if (n.member("object") != null && shapes.add(n.member("object").text())) {
                nodes.addAll(childNodes(shapesOf.shape(n.member("object").text())));
            }
        }
        return new Closure(official, shapes);
    }

    private static Set<String> officialClosure(Jv.Obj defs, String revision, Set<String> definitions) {
        Set<String> official = new TreeSet<>();
        Deque<String> todo = new ArrayDeque<>(definitions);
        while (!todo.isEmpty()) {
            String d = todo.pop();
            if (official.add(d)) {
                Jv def = defs.get(d);
                if (def == null) {
                    throw new IllegalArgumentException("MCP " + revision + " defines no " + d);
                }
                refs(def, todo);
            }
        }
        return official;
    }

    private static List<Jv> childNodes(Jv shape) {
        List<Jv> out = new java.util.ArrayList<>();
        if (shape.member("members") instanceof Jv.Obj ms) {
            ms.members().values().forEach(m -> out.add(m.member("node")));
        }
        for (Jv a : shape.member("alternatives") == null ? List.<Jv>of() : shape.member("alternatives").elements()) {
            out.add(a.member("node"));
        }
        if (shape.member("value") != null) {
            out.add(shape.member("value"));
        }
        return out;
    }

    private static void refs(Jv v, Deque<String> out) {
        if (v instanceof Jv.Obj o) {
            for (Map.Entry<String, Jv> m : o.members().entrySet()) {
                if (m.getKey().equals("$ref") && m.getValue() instanceof Jv.Str s) {
                    out.push(McpSchemaModel.refName(s.value()));
                }
                else {
                    refs(m.getValue(), out);
                }
            }
        }
        else if (v instanceof Jv.Arr a) {
            a.elements().forEach(e -> refs(e, out));
        }
    }

    /** The binding subset of a closure for one revision, in the form a {@code protocol_binding} declaration carries. */
    public Jv.Obj bindingSubset(String revision, Closure closure) {
        Jv.Obj defs = new Jv.Obj();
        for (String d : closure.definitions()) {
            defs.put(d, definition(revision, d));
        }
        McpEmbedder shapesOf = new McpEmbedder(objects, revision);
        Jv.Obj objs = new Jv.Obj();
        for (String o : closure.objects()) {
            objs.put(o, new Jv.Obj().put("kind", objects.path(o, "kind")).put("shape", shapesOf.shape(o)));
        }
        return new Jv.Obj().put("definitions", defs).put("objects", objs);
    }

    /** The definitions protocol objects in an event name, per binding revision. */
    static Map<String, Set<String>> definitionsUsed(Jv event) {
        Map<String, Set<String>> out = new TreeMap<>();
        collect(event, out);
        return out;
    }

    private static void collect(Jv v, Map<String, Set<String>> out) {
        if (v instanceof Jv.Obj o) {
            if (o.get("protocol_definition") instanceof Jv.Str d && o.get("binding_revision") instanceof Jv.Str r) {
                out.computeIfAbsent(r.value(), k -> new LinkedHashSet<>()).add(d.value());
            }
            o.members().values().forEach(x -> collect(x, out));
        }
        else if (v instanceof Jv.Arr a) {
            a.elements().forEach(x -> collect(x, out));
        }
    }
}
